"""Create original geometric film-inspired artwork. No third-party poster assets."""
from pathlib import Path
from html import escape
root=Path(__file__).resolve().parent.parent/'dist'/'art'
root.mkdir(exist_ok=True)
def save(key,title,subtitle,bg,art,fg='#eee4c9'):
    lines=title.split('|'); y=180 if len(lines)==1 else 153
    text=''.join(f'<text x="32" y="{y+i*44}" font-size="38" letter-spacing="3" font-family="Georgia,serif" fill="{fg}">{escape(line)}</text>' for i,line in enumerate(lines))
    root.joinpath(key+'.svg').write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="720" height="480" viewBox="0 0 720 480"><defs><linearGradient id="shade" x2="0" y2="1"><stop stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".45"/></linearGradient></defs><rect width="720" height="480" fill="{bg}"/>{art}<rect y="280" width="720" height="200" fill="url(#shade)"/><text x="32" y="49" fill="{fg}" opacity=".75" font-family="sans-serif" font-size="11" letter-spacing="4">THE FRAME COLLECTION</text><g transform="translate(0,205)">{text}<text x="34" y="228" font-family="sans-serif" font-size="10" letter-spacing="4" fill="{fg}" opacity=".65">{escape(subtitle)}</text></g></svg>''')
